"""Code generation strings for a file."""

import sys

declaration_pre = """
// This code conforms with the UFCx specification version {ufcx_version}
// and was automatically generated by FFCx version {ffcx_version}.
//
// This code was generated with the following options:
//
{options}

#pragma once
#include <ufcx.h>

#ifdef __cplusplus
extern "C" {{
#endif
"""

declaration_post = """
#ifdef __cplusplus
}}
#endif
"""

implementation_pre = """
// This code conforms with the UFCx specification version {ufcx_version}
// and was automatically generated by FFCx version {ffcx_version}.
//
// This code was generated with the following options:
//
{options}

// The integer-order Bessel functions jn/yn are XSI extensions rather than ISO
// C, and glibc's <math.h> hides them in strict ISO mode (e.g. -std=c17). Ask
// for the XSI declarations before any system header is included.
#ifndef _XOPEN_SOURCE
#define _XOPEN_SOURCE 700
#endif

#include <math.h>
#include <stdalign.h>
#include <stdlib.h>
#include <string.h>
#include <ufcx.h>
{extra_c_includes}

// MSVC's CRT spells the integer-order Bessel functions with a leading
// underscore and deprecates the POSIX names, so calling jn/yn directly
// is a diagnostic there. Redirect them to the CRT names, after the
// system headers so that their own declarations are not affected. No
// other C library provides the underscored names, so the mapping is
// guarded on MSVC alone.
#if defined(_MSC_VER)
#define jn(n, x) _jn((n), (x))
#define yn(n, x) _yn((n), (x))
#endif

// Keep a short loop rolled. GCC and Clang otherwise unroll small constant
// loops completely before loop vectorisation, which can leave contractions
// over a few quadrature points as scalar code; kept as a loop, each runs as
// whole SIMD vectors. Other compilers ignore the hint.
#ifndef FFCX_KEEP_ROLLED
#if defined(__clang__)
#define FFCX_KEEP_ROLLED _Pragma("clang loop unroll(disable)")
#elif defined(__GNUC__) && __GNUC__ >= 8
#define FFCX_KEEP_ROLLED _Pragma("GCC unroll 1")
#else
#define FFCX_KEEP_ROLLED
#endif
#endif

// Keep an outer loop scalar. Clang may vectorise a loop across its inner
// loops, e.g. over quadrature points or test functions, turning contiguous
// inner accesses into gathers and scatters; the inner loops vectorise
// instead. GCC does not do this, and other compilers ignore the hint.
#ifndef FFCX_NO_VECTORIZE
#if defined(__clang__)
#define FFCX_NO_VECTORIZE _Pragma("clang loop vectorize(disable)")
#else
#define FFCX_NO_VECTORIZE
#endif
#endif

"""


libraries: list[str] = [] if sys.platform.startswith("win32") else ["m"]
implementation_post = ""
